"""Wheel build hook: put the C sources into the wheel as `rtgsfit/_c`.

rtgsfit compiles the C library for each preshot, so a normal (non-editable) install needs the
Makefile and sources too. Editable installs use the checkout's `c/` directly.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from hatchling.builders.hooks.plugin.interface import BuildHookInterface

# Generated by make for the active preshot (rtgsfit.library.GENERATED_SOURCES); never packaged.
GENERATED_SOURCES = {"preshot_sizes.h", "preshot_data.c"}


class CSourcesBuildHook(BuildHookInterface):
    def initialize(self, version: str, build_data: dict[str, Any]) -> None:
        if version == "editable":
            return
        c = Path(self.root) / "c"
        if not (c / "Makefile").is_file():
            raise FileNotFoundError(f"cannot find the C sources at {c}")
        files = [c / "Makefile", *sorted(c.glob("src/*.[ch]")), *sorted(c.glob("tools/*.c"))]
        for path in files:
            if path.name not in GENERATED_SOURCES:
                build_data["force_include"][str(path)] = f"rtgsfit/_c/{path.relative_to(c).as_posix()}"
